//! Agents: who may see and change them. Generated by `cargo offrails generate resource agents name:string description:text`.

use axum::http::StatusCode;
use board::routes::paths;

use super::submit;
use crate::factories;
use crate::support::TestApp;

/// SECURITY: signed out, every route goes to sign-in and nothing is created.
#[tokio::test]
async fn signed_out_visitors_are_sent_to_sign_in() {
    let app = TestApp::new().await;
    let owner = factories::user(app.db(), "owner@example.com").await;
    let record = factories::agent(app.db(), &owner).await;
    for path in [
        paths::agents(),
        paths::new_agent(),
        paths::agent(record.id),
        paths::edit_agent(record.id),
    ] {
        app.get(&path)
            .await
            .assert_redirect_to(&paths::new_session());
    }
    for path in [
        paths::agents(),
        paths::agent(record.id),
        paths::delete_agent(record.id),
    ] {
        app.post_form(&path, &[])
            .await
            .assert_redirect_to(&paths::new_session());
    }
    assert_eq!(
        factories::reload_agent(app.db(), record.id).await,
        Some(record)
    );
}

/// SECURITY: another user's agent is 404 on every member route (it looks missing), and stays
/// as it was; the list never shows it.
#[tokio::test]
async fn another_users_agent_is_404_everywhere() {
    let app = TestApp::new().await;
    let theirs_owner = factories::user(app.db(), "them@example.com").await;
    let mut params = factories::agent_params(app.db(), &theirs_owner).await;
    params.name = "Their secret".into();
    let theirs = factories::agent_with(app.db(), &theirs_owner, params).await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    for path in [paths::agent(theirs.id), paths::edit_agent(theirs.id)] {
        app.get(&path).await.assert_status(StatusCode::NOT_FOUND);
    }
    let mine = factories::agent_params(app.db(), &me).await;
    submit(&app, &paths::agent(theirs.id), &mine)
        .await
        .assert_status(StatusCode::NOT_FOUND);
    app.post_form(&paths::delete_agent(theirs.id), &[])
        .await
        .assert_status(StatusCode::NOT_FOUND);
    assert_eq!(
        factories::reload_agent(app.db(), theirs.id).await,
        Some(theirs.clone())
    );
    app.get(&paths::agents())
        .await
        .assert_ok()
        .assert_not_contains(&format!("/agents/{}\"", theirs.id));
}
